package com.cartalaap.notification;
import java.time.Instant;import com.cartalaap.user.User;import jakarta.persistence.Column;import jakarta.persistence.Entity;import jakarta.persistence.EnumType;import jakarta.persistence.Enumerated;import jakarta.persistence.FetchType;import jakarta.persistence.GeneratedValue;import jakarta.persistence.GenerationType;import jakarta.persistence.Id;import jakarta.persistence.JoinColumn;import jakarta.persistence.ManyToOne;import jakarta.persistence.PrePersist;import jakarta.persistence.Table;
@Entity @Table(name="notifications") public class Notification{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="recipient_id")private User recipient;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="actor_id")private User actor;@Enumerated(EnumType.STRING)@Column(name="notification_type")private NotificationType type;@Column(nullable=false,length=300)private String message;@Column(name="target_id")private Long targetId;@Column(name="read_at")private Instant readAt;@Column(name="created_at")private Instant createdAt;protected Notification(){}public Notification(User recipient,User actor,NotificationType type,String message,Long targetId){this.recipient=recipient;this.actor=actor;this.type=type;this.message=message;this.targetId=targetId;}@PrePersist void onCreate(){createdAt=Instant.now();}public void markRead(){if(readAt==null)readAt=Instant.now();}public Long getId(){return id;}public User getActor(){return actor;}public NotificationType getType(){return type;}public String getMessage(){return message;}public Long getTargetId(){return targetId;}public Instant getReadAt(){return readAt;}public Instant getCreatedAt(){return createdAt;}}
